// Parse the crawl results
const results = JSON.parse($input.first().json.data.toString());

// Check if there are any updates
const hasUpdates = results.new_documents.length > 0 || results.updated_documents.length > 0;

// Format email content
let emailBody = `<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
    .header { background: #4CAF50; color: white; padding: 20px; text-align: center; }
    .content { padding: 20px; }
    .section { margin-bottom: 30px; }
    .section-title { color: #4CAF50; border-bottom: 2px solid #4CAF50; padding-bottom: 5px; }
    .document { background: #f5f5f5; padding: 15px; margin: 10px 0; border-left: 4px solid #4CAF50; }
    .document-title { font-weight: bold; color: #2196F3; }
    .document-url { color: #666; font-size: 0.9em; word-break: break-all; }
    .sections-list { margin-top: 10px; }
    .sections-list li { margin: 5px 0; }
    .stats { background: #e3f2fd; padding: 15px; border-radius: 5px; }
    .stats-item { display: inline-block; margin: 10px 20px 10px 0; }
    .stats-number { font-size: 24px; font-weight: bold; color: #2196F3; }
    .footer { background: #f5f5f5; padding: 20px; text-align: center; font-size: 0.9em; color: #666; }
    .badge { display: inline-block; padding: 3px 8px; border-radius: 3px; font-size: 0.85em; font-weight: bold; }
    .badge-new { background: #4CAF50; color: white; }
    .badge-updated { background: #FF9800; color: white; }
  </style>
</head>
<body>
  <div class="header">
    <h1>📚 Weekly RAG Document Update Report</h1>
    <p>Crawl completed on ${new Date(results.timestamp).toLocaleString()}</p>
  </div>

  <div class="content">
`;

// Statistics section
emailBody += `
    <div class="section stats">
      <div class="stats-item">
        <div class="stats-number">${results.new_documents.length}</div>
        <div>New Documents</div>
      </div>
      <div class="stats-item">
        <div class="stats-number">${results.updated_documents.length}</div>
        <div>Updated Documents</div>
      </div>
      <div class="stats-item">
        <div class="stats-number">${results.unchanged_documents.length}</div>
        <div>Unchanged</div>
      </div>
      <div class="stats-item">
        <div class="stats-number">${results.failed_urls.length}</div>
        <div>Failed</div>
      </div>
    </div>
`;

// New documents section
if (results.new_documents.length > 0) {
  emailBody += `
    <div class="section">
      <h2 class="section-title">📄 New Documents</h2>
  `;

  results.new_documents.forEach(doc => {
    emailBody += `
      <div class="document">
        <div class="document-title">
          <span class="badge badge-new">NEW</span>
          ${doc.title}
        </div>
        <div class="document-url">🔗 <a href="${doc.url}">${doc.url}</a></div>
    `;

    if (doc.sections && doc.sections.length > 0) {
      emailBody += `
        <div class="sections-list">
          <strong>Main Sections:</strong>
          <ul>
      `;
      doc.sections.slice(0, 10).forEach(section => {
        emailBody += `<li><strong>${section.heading}</strong></li>`;
      });
      if (doc.sections.length > 10) {
        emailBody += `<li><em>... and ${doc.sections.length - 10} more sections</em></li>`;
      }
      emailBody += `
          </ul>
        </div>
      `;
    }

    emailBody += `
      </div>
    `;
  });

  emailBody += `
    </div>
  `;
}

// Updated documents section
if (results.updated_documents.length > 0) {
  emailBody += `
    <div class="section">
      <h2 class="section-title">🔄 Updated Documents</h2>
  `;

  results.updated_documents.forEach(doc => {
    emailBody += `
      <div class="document">
        <div class="document-title">
          <span class="badge badge-updated">UPDATED</span>
          ${doc.title}
        </div>
        <div class="document-url">🔗 <a href="${doc.url}">${doc.url}</a></div>
    `;

    if (doc.sections && doc.sections.length > 0) {
      emailBody += `
        <div class="sections-list">
          <strong>Current Sections:</strong>
          <ul>
      `;
      doc.sections.slice(0, 10).forEach(section => {
        emailBody += `<li><strong>${section.heading}</strong></li>`;
      });
      if (doc.sections.length > 10) {
        emailBody += `<li><em>... and ${doc.sections.length - 10} more sections</em></li>`;
      }
      emailBody += `
          </ul>
        </div>
      `;
    }

    emailBody += `
      </div>
    `;
  });

  emailBody += `
    </div>
  `;
}

// Failed URLs section
if (results.failed_urls.length > 0) {
  emailBody += `
    <div class="section">
      <h2 class="section-title">⚠️ Failed URLs</h2>
      <ul>
  `;
  results.failed_urls.forEach(url => {
    emailBody += `<li>${url}</li>`;
  });
  emailBody += `
      </ul>
    </div>
  `;
}

// No updates message
if (!hasUpdates && results.failed_urls.length === 0) {
  emailBody += `
    <div class="section">
      <p style="text-align: center; font-size: 1.2em; color: #666;">
        ✅ All documents are up to date. No changes detected this week.
      </p>
    </div>
  `;
}

emailBody += `
  </div>

  <div class="footer">
    <p>This is an automated report from the RAG Learning Document Crawler</p>
    <p>Configured URLs: ${results.new_documents.length + results.updated_documents.length + results.unchanged_documents.length + results.failed_urls.length}</p>
  </div>
</body>
</html>
`;

// Return formatted data for email node
return {
  hasUpdates: hasUpdates,
  emailSubject: hasUpdates 
    ? `[RAG Learning] Weekly Update: ${results.new_documents.length} New, ${results.updated_documents.length} Updated`
    : '[RAG Learning] Weekly Update: No Changes',
  emailBody: emailBody,
  timestamp: results.timestamp,
  stats: {
    new: results.new_documents.length,
    updated: results.updated_documents.length,
    unchanged: results.unchanged_documents.length,
    failed: results.failed_urls.length
  }
};
